async function executeSummary({
	args,
	operations,
	now,
	execution,
}: CommandContext) {
	const weeks = parseWeeks(args);
	const to = now();
	const from = new Date(to.getTime() - weeks * 7 * 24 * 60 * 60 * 1000);
	const result = await runOperation(
		operations.workflows?.trainingSummary,
		"workflows.trainingSummary",
		{ weeks },
		execution,
	);
	const totalVolumeKg =
		z
			.number()
			.safeParse(
				(result.workouts as { readonly total_volume_kg?: unknown })
					.total_volume_kg,
			).data ?? 0;
	return {
		weeks,
		start_date: from.toISOString(),
		end_date: to.toISOString(),
		workout_count: result.workouts.count,
		total_duration_seconds: result.workouts.total_duration_seconds,
		exercise_count: result.workouts.exercise_count,
		set_count: result.workouts.set_count,
		total_volume_kg: totalVolumeKg,
		pages_scanned: result.workflow.pagination.workouts,
		complete: true,
	};
}

export async function execute(
	args: CliArgs,
	client: HevyClient,
	now = () => new Date(),
	readDataSource: DataSourceReader = defaultDataSourceReader,
	operations: HevyOperations = createOperations(client, {
		trainingSummaryMaxWeeks: 520,
		trainingSummaryStrictPagination: true,
	}),
	execution?: HevyExecutionOptions,
): Promise<unknown> {
	const context: CommandContext = {
		args,
		client,
		now,
		readDataSource,
		operations,
		execution,
	};
	if (args.command === "user" && !args.subcommand)
		return {
			user: {
				data: await runOperationWithoutInput(
					operations.user?.get,
					"user.get",
					context.execution,
				),
			},
		};
	if (args.command === "workouts") return executeWorkouts(context);
	if (args.command === "routines") return executeRoutines(context);
	if (args.command === "exercises") return executeExercises(context);
	if (args.command === "measurements") return executeMeasurements(context);
	if (args.command === "folders" && args.subcommand === "create")
		return executeFolderCreate(context);
	if (args.command === "summary") return executeSummary(context);
	throw new UsageError("Unknown command; run hevy --help");
}

/**
 * Build the PUT payload for a workout metadata update or exercise
 * replacement. Metadata-only updates require an explicit privacy value
 * because GET /workouts/:id does not return it.
 */
export function buildWorkoutUpdatePayload(
	current: Workout,
	patch: WorkoutMetadataPatchInput,
	replacementExercises?: WorkoutExerciseInput[],
): WorkoutUpdatePayload {
	const isMetadataOnlyUpdate = replacementExercises === undefined;
	if (isMetadataOnlyUpdate && patch.is_private === undefined) {
		throw new WorkoutPrivacyError({
			message: WORKOUT_PUT_REQUIRES_IS_PRIVATE.error,
		});
	}

	const title = patch.title !== undefined ? patch.title : current.title;
	const startTime =
		patch.start_time !== undefined
			? patch.start_time
			: normalizeFetchedWorkoutTimestamp(current.start_time);
	const endTime =
		patch.end_time !== undefined
			? patch.end_time
			: normalizeFetchedWorkoutTimestamp(current.end_time);
	const description =
		patch.description !== undefined ? patch.description : current.description;

	if (
		!Predicate.isString(title) ||
		title.length < 1 ||
		(description !== undefined &&
			description !== null &&
			!Predicate.isString(description)) ||
		!isStrictUtcTimestamp(startTime) ||
		!isStrictUtcTimestamp(endTime) ||
		(patch.is_private !== undefined && !Predicate.isBoolean(patch.is_private))
	) {
		throw new WorkoutPayloadError({
			message: "The workout metadata is invalid for an update",
		});
	}

	const payload: WorkoutUpdatePayload = {
		title,
		start_time: startTime,
		end_time: endTime,
	};
	if (description !== undefined) payload.description = description;
	if (patch.is_private !== undefined) payload.is_private = patch.is_private;
	payload.exercises =
		replacementExercises === undefined
			? preserveWorkoutExercises(current)
			: replacementExercises;
	return payload;
}

